<script setup lang="ts">
const props=defineProps<{reportId:number;plans:any[]}>();const emit=defineEmits<{changed:[]}>();const api=useApi();const toast=useToast();const saving=ref('')
async function toggle(jobId:string,itemIndex:number,actionIndex:number,action:any){const key=`${jobId}-${itemIndex}-${actionIndex}`;saving.value=key;const previous=Boolean(action.done);action.done=!previous;try{await api.ok(`/api/report/${props.reportId}/plan-actions/done`,{method:'POST',body:{job_id:jobId,item_index:itemIndex,action_index:actionIndex,done:action.done}});emit('changed')}catch(e){action.done=previous;toast.add({title:String(e),color:'error'})}finally{saving.value=''}}
</script>
<template><div class="grid gap-5"><UCard v-for="plan in plans||[]" :key="plan.job_id"><template #header><div><h3 class="text-lg font-semibold">{{plan.display_title||plan.job_title_name}}</h3><p class="text-sm muted">{{plan.narrative?.path_advice}}</p></div></template><div class="grid gap-4"><div v-for="(item,itemIndex) in plan.next_month_plan?.items||[]" :key="`${plan.job_id}-${itemIndex}`" class="rounded-lg border border-default p-4"><div class="flex items-start justify-between gap-3"><div><h4 class="font-medium">{{item.focus_label||item.focus_dimension}}</h4><p class="text-sm muted">{{item.period}} · {{item.milestone}}</p></div><UBadge :label="item.phase||'本月'" variant="soft"/></div><ul class="mt-3 list-disc space-y-1 pl-5 text-sm"><li v-for="x in item.learning_path||[]" :key="x">{{x}}</li><li v-for="x in item.practice_plan||[]" :key="x">{{x}}</li></ul><div class="mt-4 grid gap-2"><UCheckbox v-for="(action,actionIndex) in item.custom_actions||[]" :key="actionIndex" :model-value="Boolean(action.done)" :label="action.text" :disabled="saving===`${plan.job_id}-${itemIndex}-${actionIndex}`" @update:model-value="toggle(plan.job_id,Number(itemIndex),Number(actionIndex),action)"/></div></div></div></UCard></div></template>
